    q(50,"C4",["細節檢索"],"閱讀測驗","C","Why was Grass’s trip to Italy important to him?",{A:"He was inspired by a fine arts master in Italy.",B:"He formed a new interest in painting simple objects there.",C:"He developed a new form for creating his poems during the trip.",D:"He found a new way to solve the conflict between the Nazis and the Poles."},"G8",P5),
    q(51,"C4",["篇章理解"],"閱讀測驗","D","Which of the following correctly characterizes Grass’s poems, according to the passage?",{A:"Most of his poems depict the cruelty of the Nazis.",B:"The theme of his poems won him the Nobel Peace Prize.",C:"The poems on his paintings are often not related to objects in the real world.",D:"The ideas in his poems are expressed more thoroughly with the help of his paintings."},"G8",P5)
